import { z } from 'zod';
export const SOLineSchema = z.object({
    itemId: z.string().min(1, 'Item ID is required'),
    itemName: z.string().min(1, 'Item name is required'),
    qty: z.number().positive('Quantity must be positive'),
    unit: z.string().optional(),
    hsnCode: z.string().optional(),
    rate: z.number().nonnegative(),
    gstPercent: z.number().nonnegative().optional(),
    gstAmount: z.number().nonnegative().optional(),
    amount: z.number().nonnegative(),
});
export const CreateSalesOrderSchema = z.object({
    soNumber: z.string().optional(),
    customerId: z.string().min(1, 'Customer ID is required'),
    customerName: z.string().min(1, 'Customer name is required'),
    customerPhone: z.string().optional(),
    customerEmail: z.string().optional(),
    customerGstin: z.string().optional(),
    billingAddress: z.string().optional(),
    shippingAddress: z.string().optional(),
    referenceNumber: z.string().optional(),
    date: z.string().optional(),
    expectedDeliveryDate: z.string().optional(),
    paymentTerms: z.string().optional(),
    deliveryMethod: z.string().optional(),
    salesperson: z.string().optional(),
    lines: z.array(SOLineSchema).min(1, 'At least one line item is required'),
    subtotal: z.number().nonnegative(),
    taxAmount: z.number().nonnegative().optional(),
    discountPercent: z.number().nonnegative().default(0),
    discountAmount: z.number().nonnegative().default(0),
    adjustment: z.number().default(0),
    total: z.number().nonnegative(),
    customerNotes: z.string().optional(),
    terms: z.string().optional(),
    status: z.enum(['Draft', 'Confirmed', 'Packed', 'Shipped', 'Invoiced', 'Delivered', 'Cancelled']).default('Confirmed'),
});
export const CreatePackageSchema = z.object({
    soId: z.string().min(1, 'Sales Order ID is required'),
    carrier: z.string().optional(),
    trackingNumber: z.string().optional(),
});
export const CreateDeliveryChallanSchema = z.object({
    customerId: z.string().min(1, 'Customer ID is required'),
    customerName: z.string().min(1, 'Customer name is required'),
    date: z.string().optional(),
    referenceNumber: z.string().optional(),
    challanType: z.string().default('Supply on Approval / Customer Delivery'),
    lines: z.array(z.any()).min(1),
    total: z.number().nonnegative().default(0),
    status: z.enum(['Open', 'Closed', 'Delivered']).default('Open'),
});
export const SalesOrderTableDefinition = {
    tableName: 'sales_orders',
    columns: [
        'id',
        'tenant_id',
        'so_number',
        'customer_id',
        'customer_name',
        'customer_phone',
        'date',
        'expected_delivery_date',
        'payment_terms',
        'delivery_method',
        'salesperson',
        'subtotal',
        'discount_percent',
        'discount_amount',
        'adjustment',
        'total',
        'customer_notes',
        'terms',
        'status',
        'created_at',
    ],
    primaryKey: 'id',
    foreignKeys: [
        { column: 'tenant_id', references: 'client_tenants(id)' },
        { column: 'customer_id', references: 'customers(id)' },
    ],
};
